CREATE OR REPLACE FUNCTION public.confirm_order_payment(p_thanhtoanid bigint, p_success boolean, p_ghichu text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE payment public."ThanhToan"%ROWTYPE; order_row public."DonHang"%ROWTYPE; invoice public."HoaDon"%ROWTYPE;
 order_id bigint; paid_total numeric; target_status text;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(private.is_staff(),false) THEN RAISE EXCEPTION 'An active staff account is required'; END IF;
 IF p_success IS NULL THEN RAISE EXCEPTION 'A payment outcome is required'; END IF;
 SELECT "DonHangID" INTO order_id FROM public."ThanhToan" WHERE "ThanhToanID"=p_thanhtoanid;
 IF NOT FOUND THEN RAISE EXCEPTION 'Payment not found'; END IF;
 -- Every path locks order before payment/invoice: matches Web and request RPC.
 SELECT * INTO order_row FROM public."DonHang" WHERE "DonHangID"=order_id FOR UPDATE;
 SELECT * INTO payment FROM public."ThanhToan" WHERE "ThanhToanID"=p_thanhtoanid FOR UPDATE;
 IF payment."DonHangID"<>order_id THEN RAISE EXCEPTION 'Payment order changed'; END IF;
 target_status:=CASE WHEN p_success THEN 'Thành công' ELSE 'Thất bại' END;
 IF payment."TrangThai"=target_status THEN
  RETURN;
 END IF;
 IF payment."TrangThai"<>'Chờ thanh toán' THEN RAISE EXCEPTION 'Only pending payments can be confirmed'; END IF;
 IF order_row."TrangThai"='Đã hủy' THEN RAISE EXCEPTION 'Canceled orders cannot accept payments'; END IF;
 SELECT * INTO invoice FROM public."HoaDon" WHERE "DonHangID"=order_id ORDER BY "HoaDonID" LIMIT 1 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
 SELECT coalesce(sum("SoTien"),0) INTO paid_total FROM public."ThanhToan" WHERE "DonHangID"=order_id AND "TrangThai"='Thành công';
 IF p_success AND (payment."SoTien"<=0 OR paid_total+payment."SoTien">invoice."ThanhTien") THEN RAISE EXCEPTION 'Payment exceeds the remaining invoice balance'; END IF;
 UPDATE public."ThanhToan" SET "TrangThai"=target_status,"ThoiGian"=now(),"GhiChu"=coalesce(nullif(btrim(p_ghichu),''),"GhiChu") WHERE "ThanhToanID"=p_thanhtoanid;
 IF p_success THEN
  paid_total:=paid_total+payment."SoTien";
  IF paid_total>=invoice."ThanhTien" THEN
   UPDATE public."HoaDon" SET "TrangThai"='Đã thanh toán' WHERE "HoaDonID"=invoice."HoaDonID";
   IF order_row."TrangThai"='Đã giao' THEN UPDATE public."DonHang" SET "TrangThai"='Đã thanh toán',"NgayCapNhat"=now() WHERE "DonHangID"=order_id; END IF;
  END IF;
 END IF;
 RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.hide_chat_message(p_message_id integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  account_id integer;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;
  account_id := private.current_account_id();
  IF account_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public."TinNhan" AS message
    WHERE message."TinNhanID" = p_message_id
      AND (
        message."NguoiGuiID" = account_id
        OR message."NguoiNhanID" = account_id
        OR (
          message."DonHangID" IS NOT NULL
          AND private.can_access_order(message."DonHangID"::bigint)
        )
      )
  ) THEN
    RETURN false;
  END IF;

  INSERT INTO public."TinNhanAn" ("TaiKhoanID", "TinNhanID")
  VALUES (account_id, p_message_id)
  ON CONFLICT DO NOTHING;
  RETURN true;
END
$function$

CREATE OR REPLACE FUNCTION public.mark_notifications_read(p_notification_ids bigint[] DEFAULT NULL::bigint[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  current_account_id bigint := (SELECT private.current_account_id());
  updated_count integer;
BEGIN
  IF (SELECT auth.uid()) IS NULL OR current_account_id IS NULL THEN
    RAISE EXCEPTION 'An active account is required';
  END IF;

  UPDATE public."ThongBao"
  SET "DaDoc" = true
  WHERE "TaiKhoanID" = current_account_id
    AND "DaDoc" = false
    AND (
      p_notification_ids IS NULL
      OR "ThongBaoID" = ANY (p_notification_ids)
    );

  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_generated_booking_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW."MaBooking" LIKE 'BK-%' THEN
    NEW."MaBooking" := 'BK' || lpad(
      NEW."BookingID"::text,
      greatest(4, length(NEW."BookingID"::text)),
      '0'
    );
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.register_push_device_token(p_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  account_id bigint;
BEGIN
  IF auth.uid() IS NULL OR p_token IS NULL OR length(p_token) < 20 THEN
    RAISE EXCEPTION 'A signed-in user and valid device token are required';
  END IF;

  account_id := private.current_account_id();
  IF account_id IS NULL THEN
    RAISE EXCEPTION 'No active application account is associated with this user';
  END IF;

  -- A device token belongs to one account at a time. Reassignment also cleans
  -- up tokens left behind by an interrupted sign-out.
  DELETE FROM public.push_device_tokens WHERE token = p_token;
  INSERT INTO public.push_device_tokens (token, "TaiKhoanID", platform, updated_at)
  VALUES (p_token, account_id::integer, 'android', now());
END;
$function$

CREATE OR REPLACE FUNCTION public.save_customer_address(p_diachiid bigint, p_tennguoinhan text, p_sodienthoai text, p_diachi text, p_ghichu text, p_macdinh boolean)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
	customer_id bigint := (SELECT private.current_customer_id());
	address_id bigint;
BEGIN
	IF (SELECT auth.uid()) IS NULL OR customer_id IS NULL THEN
		RAISE EXCEPTION 'An active customer account is required';
	END IF;
	IF nullif(btrim(p_diachi), '') IS NULL THEN
		RAISE EXCEPTION 'Address is required';
	END IF;

	IF p_diachiid IS NULL THEN
		INSERT INTO public.khachhang_diachi (
			khachhangid,
			tennguoinhan,
			sodienthoai,
			diachi,
			ghichu,
			macdinh
		) VALUES (
			customer_id,
			nullif(btrim(p_tennguoinhan), ''),
			nullif(btrim(p_sodienthoai), ''),
			btrim(p_diachi),
			nullif(btrim(p_ghichu), ''),
			false
		) RETURNING diachiid INTO address_id;
	ELSE
		UPDATE public.khachhang_diachi
		SET tennguoinhan = nullif(btrim(p_tennguoinhan), ''),
			sodienthoai = nullif(btrim(p_sodienthoai), ''),
			diachi = btrim(p_diachi),
			ghichu = nullif(btrim(p_ghichu), '')
		WHERE diachiid = p_diachiid
			AND khachhangid = customer_id
		RETURNING diachiid INTO address_id;

		IF address_id IS NULL THEN
			RAISE EXCEPTION 'Address not found';
		END IF;
	END IF;

	IF coalesce(p_macdinh, false) THEN
		UPDATE public.khachhang_diachi
		SET macdinh = false
		WHERE khachhangid = customer_id
			AND macdinh;

		UPDATE public.khachhang_diachi
		SET macdinh = true
		WHERE diachiid = address_id
			AND khachhangid = customer_id;
	END IF;

	RETURN address_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_booking_promotion(p_bookingid bigint, p_makhuyenmai text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := (SELECT private.current_customer_id());
  booking_row public."Booking"%ROWTYPE;
  promotion public."KhuyenMai"%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL OR customer_id IS NULL THEN
    RAISE EXCEPTION 'An active customer account is required';
  END IF;

  SELECT *
  INTO booking_row
  FROM public."Booking"
  WHERE "BookingID" = p_bookingid
    AND "KhachHangID" = customer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found';
  END IF;

  SELECT *
  INTO promotion
  FROM public."KhuyenMai"
  WHERE upper("MaKhuyenMai") = upper(btrim(p_makhuyenmai))
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Promotion code does not exist';
  END IF;

  IF booking_row."KhuyenMaiID" IS NOT NULL THEN
    IF booking_row."KhuyenMaiID" = promotion."KhuyenMaiID" THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'A promotion has already been reserved for this booking';
  END IF;

  IF booking_row."TrangThai" <> 'ChoTiepNhan'
     OR EXISTS (
       SELECT 1
       FROM public."DonHang"
       WHERE "BookingID" = p_bookingid
     ) THEN
    RAISE EXCEPTION 'Only pending bookings can use a promotion';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public."Booking" AS existing_booking
    WHERE existing_booking."KhachHangID" = customer_id
      AND existing_booking."KhuyenMaiID" = promotion."KhuyenMaiID"
      AND existing_booking."TrangThai" <> 'DaHuy'
  ) THEN
    RAISE EXCEPTION 'Promotion has already been used by this customer';
  END IF;

  IF promotion."TrangThai" <> 'Hoạt động'
     OR promotion."NgayBatDau" > current_date
     OR promotion."NgayKetThuc" < current_date
     OR (
       promotion."SoLuongSuDung" IS NOT NULL
       AND promotion."SoLuongSuDung" <= 0
     ) THEN
    RAISE EXCEPTION 'Promotion code is invalid, expired, or unavailable';
  END IF;

  IF promotion."SoLuongSuDung" IS NOT NULL THEN
    UPDATE public."KhuyenMai"
    SET "SoLuongSuDung" = "SoLuongSuDung" - 1
    WHERE "KhuyenMaiID" = promotion."KhuyenMaiID"
      AND "SoLuongSuDung" > 0;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Promotion code is no longer available';
    END IF;
  END IF;

  UPDATE public."Booking"
  SET "KhuyenMaiID" = promotion."KhuyenMaiID",
      "KhuyenMaiDaTru" = promotion."SoLuongSuDung" IS NOT NULL
  WHERE "BookingID" = p_bookingid;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_laundry_booking_request(p_items jsonb, p_hinhthucnhando text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid, p_use_points boolean, p_phuongthucthanhtoan text, p_makhuyenmai text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  booking_result jsonb;
  customer_id bigint := (SELECT private.current_customer_id());
BEGIN
  IF p_phuongthucthanhtoan IS NULL
     OR p_phuongthucthanhtoan NOT IN ('Tiền mặt', 'Chuyển khoản') THEN
    RAISE EXCEPTION 'Unsupported payment method';
  END IF;

  booking_result := public.submit_laundry_booking_request(
    p_items => p_items,
    p_hinhthucnhando => p_hinhthucnhando,
    p_diachinhan => p_diachinhan,
    p_ngayhen => p_ngayhen,
    p_giohen => p_giohen,
    p_ghichu => p_ghichu,
    p_idempotency_key => p_idempotency_key,
    p_use_points => p_use_points,
    p_makhuyenmai => p_makhuyenmai
  );

  UPDATE public."Booking"
  SET "PhuongThucThanhToan" = p_phuongthucthanhtoan
  WHERE "BookingID" = (booking_result->>'bookingid')::bigint
    AND "KhachHangID" = customer_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found for current customer';
  END IF;

  RETURN booking_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_laundry_booking_with_delivery(p_items jsonb, p_hinhthucnhando text, p_hinhthucgiaodo text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid, p_use_points boolean, p_phuongthucthanhtoan text, p_makhuyenmai text DEFAULT NULL::text, p_diachigiao text DEFAULT NULL::text, p_delivery_fee_quote_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  booking_result jsonb;
  customer_id bigint := (SELECT private.current_customer_id());
  current_user_id uuid := (SELECT auth.uid());
  booking_id bigint;
  quote_row public.delivery_fee_quotes%ROWTYPE;
  pickup_distance integer := 0;
  delivery_distance integer := 0;
  pickup_fee numeric(12, 2) := 0;
  delivery_fee numeric(12, 2) := 0;
  total_delivery_fee numeric(12, 2) := 0;
  pickup_address text;
  delivery_address text;
BEGIN
  IF current_user_id IS NULL OR customer_id IS NULL THEN
    RAISE EXCEPTION 'An active customer account is required';
  END IF;
  IF p_hinhthucnhando NOT IN ('Tại cửa hàng', 'Tại nhà')
     OR p_hinhthucgiaodo NOT IN ('Tại cửa hàng', 'Tại nhà') THEN
    RAISE EXCEPTION 'Unsupported delivery method';
  END IF;
  IF p_hinhthucnhando = 'Tại nhà'
     AND nullif(btrim(COALESCE(p_diachinhan, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Pickup address is required';
  END IF;
  IF p_hinhthucgiaodo = 'Tại nhà'
     AND nullif(btrim(COALESCE(p_diachigiao, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Delivery address is required';
  END IF;

  pickup_address := CASE WHEN p_hinhthucnhando = 'Tại nhà'
    THEN nullif(btrim(p_diachinhan), '') ELSE NULL END;
  delivery_address := CASE WHEN p_hinhthucgiaodo = 'Tại nhà'
    THEN nullif(btrim(p_diachigiao), '') ELSE NULL END;

  IF pickup_address IS NOT NULL OR delivery_address IS NOT NULL THEN
    IF p_delivery_fee_quote_id IS NULL THEN
      RAISE EXCEPTION 'A current delivery fee quote is required';
    END IF;

    SELECT * INTO quote_row
    FROM public.delivery_fee_quotes
    WHERE id = p_delivery_fee_quote_id
    FOR UPDATE;

    IF NOT FOUND
       OR quote_row.auth_user_id <> current_user_id
       OR (
         pickup_address IS NULL
         AND quote_row.pickup_address_hash IS NOT NULL
       )
       OR (
         pickup_address IS NOT NULL
         AND quote_row.pickup_address_hash IS DISTINCT FROM
           encode(extensions.digest(convert_to(btrim(pickup_address), 'UTF8'), 'sha256'), 'hex')
       )
       OR (
         delivery_address IS NULL
         AND quote_row.delivery_address_hash IS NOT NULL
       )
       OR (
         delivery_address IS NOT NULL
         AND quote_row.delivery_address_hash IS DISTINCT FROM
           encode(extensions.digest(convert_to(btrim(delivery_address), 'UTF8'), 'sha256'), 'hex')
       )
       OR (
         quote_row.expires_at <= now()
         AND quote_row.consumed_booking_id IS NULL
       ) THEN
      RAISE EXCEPTION 'Delivery fee quote is invalid or expired';
    END IF;

    IF quote_row.consumed_booking_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public."Booking"
      WHERE "BookingID" = quote_row.consumed_booking_id
        AND "KhachHangID" = customer_id
        AND "IdempotencyKey" = p_idempotency_key
    ) THEN
      RAISE EXCEPTION 'Delivery fee quote has already been used';
    END IF;

    pickup_distance := CASE WHEN pickup_address IS NOT NULL
      THEN quote_row.pickup_distance_meters ELSE 0 END;
    delivery_distance := CASE WHEN delivery_address IS NOT NULL
      THEN quote_row.delivery_distance_meters ELSE 0 END;

    -- First 3,000 meters are free on each leg. Each additional meter costs
    -- 5 VND; round the fee up to the next 1,000 VND.
    pickup_fee := ceil(greatest(pickup_distance - 3000, 0)::numeric * 5 / 1000) * 1000;
    delivery_fee := ceil(greatest(delivery_distance - 3000, 0)::numeric * 5 / 1000) * 1000;
  ELSIF p_delivery_fee_quote_id IS NOT NULL THEN
    RAISE EXCEPTION 'A delivery fee quote was supplied without a home delivery leg';
  END IF;

  -- Defer point redemption until the verified fee has been stored.
  booking_result := public.submit_laundry_booking_request(
    p_items => p_items,
    p_hinhthucnhando => p_hinhthucnhando,
    p_diachinhan => p_diachinhan,
    p_ngayhen => p_ngayhen,
    p_giohen => p_giohen,
    p_ghichu => p_ghichu,
    p_idempotency_key => p_idempotency_key,
    p_use_points => false,
    p_phuongthucthanhtoan => p_phuongthucthanhtoan,
    p_makhuyenmai => p_makhuyenmai
  );

  booking_id := (booking_result->>'bookingid')::bigint;
  IF p_delivery_fee_quote_id IS NOT NULL
     AND quote_row.consumed_booking_id IS NOT NULL
     AND quote_row.consumed_booking_id <> booking_id THEN
    RAISE EXCEPTION 'Delivery fee quote has already been used';
  END IF;
  total_delivery_fee := pickup_fee + delivery_fee;

  UPDATE public."Booking"
  SET "HinhThucGiaoDo" = p_hinhthucgiaodo,
      "DiaChiGiao" = delivery_address,
      "PickupDistanceMeters" = pickup_distance,
      "PickupDeliveryFee" = pickup_fee,
      "DeliveryDistanceMeters" = delivery_distance,
      "DeliveryFee" = delivery_fee
  WHERE "BookingID" = booking_id
    AND "KhachHangID" = customer_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found for current customer';
  END IF;

  IF p_delivery_fee_quote_id IS NOT NULL THEN
    UPDATE public.delivery_fee_quotes
    SET consumed_booking_id = booking_id
    WHERE id = p_delivery_fee_quote_id;
  END IF;

  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'Booking'
      AND column_name = 'HinhThucTraDo'
  ) THEN
    EXECUTE 'UPDATE public."Booking" SET "HinhThucTraDo" = $1 WHERE "BookingID" = $2'
      USING p_hinhthucgiaodo, booking_id;
  END IF;
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'Booking'
      AND column_name = 'DiaChiTra'
  ) THEN
    EXECUTE 'UPDATE public."Booking" SET "DiaChiTra" = $1 WHERE "BookingID" = $2'
      USING delivery_address, booking_id;
  END IF;

  IF p_items IS NOT NULL AND coalesce(p_use_points, false) THEN
    booking_result := public.submit_laundry_order_cart_with_points(
      p_items,
      p_hinhthucnhando,
      p_diachinhan,
      p_ngayhen,
      p_giohen,
      p_ghichu,
      p_idempotency_key,
      true
    );
  END IF;

  RETURN booking_result || jsonb_build_object(
    'pickupdistancemeters', pickup_distance,
    'pickupdeliveryfee', pickup_fee,
    'deliverydistancemeters', delivery_distance,
    'deliveryfee', delivery_fee,
    'totaldeliveryfee', total_delivery_fee
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_laundry_booking_with_requested_services(p_items jsonb, p_hinhthucnhando text, p_hinhthucgiaodo text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid, p_use_points boolean, p_phuongthucthanhtoan text, p_makhuyenmai text DEFAULT NULL::text, p_diachigiao text DEFAULT NULL::text, p_delivery_fee_quote_id uuid DEFAULT NULL::uuid, p_requested_services jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  booking_result jsonb;
  booking_id integer;
  customer_id integer := (SELECT private.current_customer_id());
BEGIN
  IF customer_id IS NULL OR (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'An active customer account is required';
  END IF;
  IF p_requested_services IS NOT NULL
     AND jsonb_typeof(p_requested_services) <> 'array' THEN
    RAISE EXCEPTION 'Requested services must be a JSON array';
  END IF;
  IF jsonb_array_length(coalesce(p_requested_services, '[]'::jsonb)) > 50 THEN
    RAISE EXCEPTION 'A booking can contain at most 50 requested services';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(coalesce(p_requested_services, '[]'::jsonb)) AS request(item)
    WHERE jsonb_typeof(item) <> 'object'
       OR coalesce(item->>'service_id', '') !~ '^[1-9][0-9]*$'
       OR coalesce(item->>'garment_id', '') !~ '^[1-9][0-9]*$'
       OR coalesce(item->>'unit_id', '') !~ '^[1-9][0-9]*$'
  ) THEN
    RAISE EXCEPTION 'Each requested service needs valid service, garment, and unit IDs';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(coalesce(p_requested_services, '[]'::jsonb)) AS request(
      service_id integer,
      garment_id integer,
      unit_id integer
    )
    WHERE NOT EXISTS (
      SELECT 1
      FROM public."BangGia" AS price
      WHERE price."DichVuID" = request.service_id
        AND price."LoaiDoGiatID" = request.garment_id
        AND price."DonViTinhID" = request.unit_id
        AND price."TrangThai" = 'Hoạt động'
    )
  ) THEN
    RAISE EXCEPTION 'A requested service is no longer available';
  END IF;

  booking_result := public.submit_laundry_booking_with_delivery(
    p_items => p_items,
    p_hinhthucnhando => p_hinhthucnhando,
    p_hinhthucgiaodo => p_hinhthucgiaodo,
    p_diachinhan => p_diachinhan,
    p_ngayhen => p_ngayhen,
    p_giohen => p_giohen,
    p_ghichu => p_ghichu,
    p_idempotency_key => p_idempotency_key,
    p_use_points => p_use_points,
    p_phuongthucthanhtoan => p_phuongthucthanhtoan,
    p_makhuyenmai => p_makhuyenmai,
    p_diachigiao => p_diachigiao,
    p_delivery_fee_quote_id => p_delivery_fee_quote_id
  );
  booking_id := (booking_result->>'bookingid')::integer;

  IF NOT EXISTS (
    SELECT 1
    FROM public."Booking"
    WHERE "BookingID" = booking_id
      AND "KhachHangID" = customer_id
      AND "TrangThai" = 'ChoTiepNhan'
  ) THEN
    RETURN booking_result;
  END IF;

  DELETE FROM public."BookingYeuCauDichVu"
  WHERE "BookingID" = booking_id;

  INSERT INTO public."BookingYeuCauDichVu" (
    "BookingID", "DichVuID", "LoaiDoGiatID", "DonViTinhID"
  )
  SELECT booking_id, service_id, garment_id, unit_id
  FROM jsonb_to_recordset(coalesce(p_requested_services, '[]'::jsonb)) AS request(
    service_id integer,
    garment_id integer,
    unit_id integer
  );

  RETURN booking_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_laundry_booking_without_details(p_hinhthucnhando text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := (SELECT private.current_customer_id());
  existing_booking record;
  booking_id bigint;
  booking_number text;
BEGIN
  IF customer_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_idempotency_key IS NULL THEN RAISE EXCEPTION 'An idempotency key is required'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_idempotency_key::text,0));
  IF p_hinhthucnhando IS NULL OR p_hinhthucnhando NOT IN ('Tại cửa hàng','Tại nhà') THEN RAISE EXCEPTION 'Unsupported pickup method'; END IF;
  IF p_hinhthucnhando='Tại nhà' AND nullif(btrim(p_diachinhan),'') IS NULL THEN RAISE EXCEPTION 'A pickup address is required'; END IF;
  IF p_ngayhen IS NULL OR p_ngayhen<current_date OR p_giohen IS NULL THEN RAISE EXCEPTION 'A current pickup appointment is required'; END IF;
  SELECT * INTO existing_booking
  FROM public."Booking"
  WHERE "IdempotencyKey" = p_idempotency_key
    AND "KhachHangID" = customer_id;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'bookingid', existing_booking."BookingID",
      'mabooking', existing_booking."MaBooking",
      'trangthai', existing_booking."TrangThai",
      'thanhtien', 0,
      'itemcount', 0
    );
  END IF;
  IF EXISTS(SELECT 1 FROM public."Booking" WHERE "IdempotencyKey"=p_idempotency_key) THEN RAISE EXCEPTION 'Idempotency key is already in use'; END IF;
  booking_number := 'BK-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISS') ||
    '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8);
  INSERT INTO public."Booking" (
    "MaBooking", "KhachHangID", "HinhThucNhanDo", "DiaChiNhan", "HinhThucTraDo",
    "NgayHen", "GioHen", "GhiChu", "TrangThai", "IdempotencyKey"
  ) VALUES (
    booking_number, customer_id, p_hinhthucnhando,
    nullif(btrim(p_diachinhan), ''), 'Tại cửa hàng', p_ngayhen, p_giohen,
    nullif(btrim(p_ghichu), ''), 'ChoTiepNhan', p_idempotency_key
  ) RETURNING "BookingID", "MaBooking" INTO booking_id, booking_number;
  RETURN jsonb_build_object(
    'bookingid', booking_id,
    'mabooking', booking_number,
    'trangthai', 'ChoTiepNhan',
    'thanhtien', 0,
    'itemcount', 0
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_laundry_order(p_banggiaid bigint, p_measurement numeric, p_hinhthucnhando text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb; detail_id bigint;
BEGIN
 result:=public.submit_laundry_order_cart(jsonb_build_array(jsonb_build_object('banggiaid',p_banggiaid,'measurement',p_measurement)),p_hinhthucnhando,p_diachinhan,p_ngayhen,p_giohen,p_ghichu,p_idempotency_key);
 SELECT min("ChiTietBookingID") INTO detail_id FROM public."ChiTietBooking" WHERE "BookingID"=(result->>'bookingid')::bigint;
 RETURN result||jsonb_build_object('chitietbookingid',detail_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_laundry_order_cart(p_items jsonb, p_hinhthucnhando text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := private.current_customer_id();
  booking_row public."Booking"%ROWTYPE;
  booking_id bigint;
  detail_count integer := 0;
  total_amount numeric := 0;
  item jsonb;
  price_row record;
  measurement numeric;
  quantity numeric;
  weight_kg numeric;
  line_total numeric;
BEGIN
  IF auth.uid() IS NULL OR customer_id IS NULL THEN
    RAISE EXCEPTION 'An active customer account is required';
  END IF;
  IF p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'An idempotency key is required';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_idempotency_key::text, 0)
  );

  SELECT * INTO booking_row
  FROM public."Booking"
  WHERE "IdempotencyKey" = p_idempotency_key;

  IF FOUND THEN
    IF booking_row."KhachHangID" <> customer_id THEN
      RAISE EXCEPTION 'Idempotency key is already in use';
    END IF;

    SELECT count(*), coalesce(sum("ThanhTien"), 0)
    INTO detail_count, total_amount
    FROM public."ChiTietBooking"
    WHERE "BookingID" = booking_row."BookingID";

    RETURN jsonb_build_object(
      'bookingid', booking_row."BookingID",
      'mabooking', booking_row."MaBooking",
      'trangthai', booking_row."TrangThai",
      'thanhtien', total_amount,
      'itemcount', detail_count
    );
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Cart must contain at least one item';
  END IF;
  IF p_hinhthucnhando IS NULL
     OR p_hinhthucnhando NOT IN ('Tại cửa hàng', 'Tại nhà') THEN
    RAISE EXCEPTION 'Unsupported pickup method';
  END IF;
  IF p_hinhthucnhando = 'Tại nhà'
     AND nullif(btrim(p_diachinhan), '') IS NULL THEN
    RAISE EXCEPTION 'A pickup address is required';
  END IF;
  IF p_ngayhen IS NULL OR p_ngayhen < current_date OR p_giohen IS NULL THEN
    RAISE EXCEPTION 'A current pickup appointment is required';
  END IF;

  INSERT INTO public."Booking" (
    "MaBooking", "KhachHangID", "HinhThucNhanDo", "DiaChiNhan",
    "HinhThucTraDo", "NgayHen", "GioHen", "GhiChu", "TrangThai",
    "IdempotencyKey"
  ) VALUES (
    'BK-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 24),
    customer_id,
    p_hinhthucnhando,
    CASE WHEN p_hinhthucnhando = 'Tại nhà' THEN nullif(btrim(p_diachinhan), '') END,
    'Tại cửa hàng',
    p_ngayhen,
    p_giohen,
    nullif(btrim(p_ghichu), ''),
    'ChoTiepNhan',
    p_idempotency_key
  )
  RETURNING "BookingID" INTO booking_id;

  UPDATE public."Booking"
  SET "MaBooking" = 'BK' || lpad(
    booking_id::text,
    greatest(4, length(booking_id::text)),
    '0'
  )
  WHERE "BookingID" = booking_id;

  FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    SELECT bg.*,
      lower(btrim(coalesce(u."KyHieu", u."TenDonViTinh"))) AS unit_symbol
    INTO price_row
    FROM public."BangGia" chosen
    JOIN public."BangGia" bg
      ON bg."DichVuID" = chosen."DichVuID"
      AND bg."LoaiDoGiatID" = chosen."LoaiDoGiatID"
      AND bg."DonViTinhID" = chosen."DonViTinhID"
    JOIN public."DonViTinh" u ON u."DonViTinhID" = bg."DonViTinhID"
    WHERE chosen."BangGiaID" = (item->>'banggiaid')::bigint
      AND bg."TrangThai" = 'Hoạt động'
      AND (bg."NgayApDung" IS NULL OR bg."NgayApDung" <= current_date)
      AND (bg."NgayKetThuc" IS NULL OR bg."NgayKetThuc" >= current_date)
    ORDER BY bg."NgayApDung" DESC NULLS LAST, bg."BangGiaID" DESC
    LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'No effective price is available for the selected tuple';
    END IF;

    measurement := (item->>'measurement')::numeric;
    IF measurement IS NULL OR measurement <= 0 OR measurement > 99999999.99 THEN
      RAISE EXCEPTION 'Invalid measurement';
    END IF;

    IF price_row.unit_symbol IN ('kg', 'kgs', 'kilogram') THEN
      measurement := round(measurement, 2);
      IF measurement <= 0 THEN
        RAISE EXCEPTION 'Invalid measurement';
      END IF;
      weight_kg := measurement;
      quantity := NULL;
      line_total := round(price_row."DonGia" * measurement, 0);
    ELSE
      IF measurement <> trunc(measurement) THEN
        RAISE EXCEPTION 'Piece quantity must be an integer';
      END IF;
      quantity := measurement;
      weight_kg := NULL;
      line_total := round(price_row."DonGia" * measurement, 0);
    END IF;

    INSERT INTO public."ChiTietBooking" (
      "BookingID", "DichVuID", "LoaiDoGiatID", "DonViTinhID",
      "SoLuong", "KhoiLuong", "DonGia", "ThanhTien", "GhiChu"
    ) VALUES (
      booking_id, price_row."DichVuID", price_row."LoaiDoGiatID",
      price_row."DonViTinhID", quantity, weight_kg, price_row."DonGia",
      line_total, nullif(btrim(p_ghichu), '')
    );

    detail_count := detail_count + 1;
    total_amount := total_amount + line_total;
  END LOOP;

  SELECT * INTO booking_row
  FROM public."Booking"
  WHERE "BookingID" = booking_id;

  RETURN jsonb_build_object(
    'bookingid', booking_id,
    'mabooking', booking_row."MaBooking",
    'trangthai', 'ChoTiepNhan',
    'thanhtien', total_amount,
    'itemcount', detail_count
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_laundry_order_cart_with_points(p_items jsonb, p_hinhthucnhando text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid, p_use_points boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := (SELECT private.current_customer_id());
  booking_result jsonb;
  booking_id bigint;
  booking_row public."Booking"%ROWTYPE;
  promotion public."KhuyenMai"%ROWTYPE;
  available_points integer := 0;
  points_to_use integer := 0;
  points_discount numeric(18,2) := 0;
  promotion_discount numeric(18,2) := 0;
  total_amount numeric(18,2) := 0;
  total_delivery_fee numeric(12,2) := 0;
  remaining_points integer := 0;
BEGIN
  IF customer_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  booking_result := public.submit_laundry_order_cart(
    p_items,
    p_hinhthucnhando,
    p_diachinhan,
    p_ngayhen,
    p_giohen,
    p_ghichu,
    p_idempotency_key
  );
  booking_id := (booking_result->>'bookingid')::bigint;

  SELECT *
  INTO booking_row
  FROM public."Booking"
  WHERE "BookingID" = booking_id
    AND "KhachHangID" = customer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found';
  END IF;

  SELECT COALESCE(SUM("ThanhTien"), 0)
  INTO total_amount
  FROM public."ChiTietBooking"
  WHERE "BookingID" = booking_id;

  total_delivery_fee := coalesce(booking_row."PickupDeliveryFee", 0)
    + coalesce(booking_row."DeliveryFee", 0);

  IF booking_row."KhuyenMaiID" IS NOT NULL THEN
    SELECT *
    INTO promotion
    FROM public."KhuyenMai"
    WHERE "KhuyenMaiID" = booking_row."KhuyenMaiID";

    IF FOUND
       AND promotion."TrangThai" = 'Hoạt động'
       AND promotion."NgayBatDau" <= current_date
       AND promotion."NgayKetThuc" >= current_date
       AND (
         promotion."GiaTriDonToiThieu" IS NULL
         OR total_amount >= promotion."GiaTriDonToiThieu"
       ) THEN
      promotion_discount := CASE
        WHEN promotion."LoaiKhuyenMai" = 'Phần trăm'
          THEN total_amount * promotion."GiaTriGiam" / 100
        ELSE promotion."GiaTriGiam"
      END;
      IF promotion."MucGiamToiDa" IS NOT NULL THEN
        promotion_discount := least(
          promotion_discount,
          promotion."MucGiamToiDa"
        );
      END IF;
      promotion_discount := greatest(
        least(promotion_discount, total_amount),
        0
      );
    END IF;
  END IF;

  IF NOT booking_row."DiemDaTru" THEN
    IF coalesce(p_use_points, false) THEN
      SELECT "DiemHienTai"
      INTO available_points
      FROM public."DiemTichLuy"
      WHERE "KhachHangID" = customer_id
      FOR UPDATE;

      IF FOUND THEN
        points_to_use := least(
          available_points::numeric,
          floor(greatest(
            total_amount - promotion_discount + total_delivery_fee,
            0
          ))
        )::integer;
        points_discount := points_to_use;

        IF points_to_use > 0 THEN
          UPDATE public."DiemTichLuy"
          SET
            "DiemHienTai" = "DiemHienTai" - points_to_use,
            "NgayCapNhat" = now()
          WHERE "KhachHangID" = customer_id;
        END IF;
      END IF;
    END IF;

    UPDATE public."Booking"
    SET
      "DiemSuDung" = points_to_use,
      "TienGiamDoDiem" = points_discount,
      "DiemDaTru" = true
    WHERE "BookingID" = booking_id;
  ELSE
    points_to_use := booking_row."DiemSuDung";
    points_discount := booking_row."TienGiamDoDiem";
  END IF;

  SELECT COALESCE("DiemHienTai", 0)
  INTO remaining_points
  FROM public."DiemTichLuy"
  WHERE "KhachHangID" = customer_id;
  remaining_points := COALESCE(remaining_points, 0);

  RETURN booking_result || jsonb_build_object(
    'thanhtien', total_amount,
    'diemsudung', points_to_use,
    'tiengiamdodiem', points_discount,
    'tiengiamkhuyenmai', promotion_discount,
    'thanhtoan', greatest(
      total_amount + total_delivery_fee
        - points_discount - promotion_discount,
      0
    ),
    'diemconlai', remaining_points
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_order_review(p_donhangid bigint, p_sosao integer, p_binhluan text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := (SELECT private.current_customer_id());
  review_id bigint;
BEGIN
  IF customer_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_sosao < 1 OR p_sosao > 5 THEN
    RAISE EXCEPTION 'Rating must be between 1 and 5';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public."DonHang" AS order_record
    WHERE order_record."DonHangID" = p_donhangid
      AND order_record."KhachHangID" = customer_id
      AND order_record."TrangThai" IN ('Đã giao', 'Đã thanh toán')
  ) THEN
    RAISE EXCEPTION 'Only completed customer orders can be reviewed';
  END IF;

  INSERT INTO public."DanhGia" (
    "DonHangID", "KhachHangID", "SoSao", "BinhLuan", "NgayDanhGia", "TrangThai"
  ) VALUES (
    p_donhangid::integer,
    customer_id::integer,
    p_sosao,
    nullif(left(btrim(p_binhluan), 1000), ''),
    now(),
    'Hiển thị'
  )
  ON CONFLICT ("DonHangID") DO UPDATE
  SET "SoSao" = EXCLUDED."SoSao",
      "BinhLuan" = EXCLUDED."BinhLuan",
      "NgayDanhGia" = now(),
      "TrangThai" = 'Hiển thị'
  RETURNING "DanhGiaID" INTO review_id;

  RETURN jsonb_build_object('danhgiaid', review_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.transition_laundry_order(p_donhangid bigint, p_trangthaimoi text, p_lydo text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  order_record public."DonHang"%ROWTYPE;
  valid_transition boolean := false;
  current_employee bigint := (SELECT private.current_employee_id());
  current_account bigint := (
    SELECT "TaiKhoanID"
    FROM public."TaiKhoan"
    WHERE "UserAuthId" = (SELECT auth.uid())
    LIMIT 1
  );
  customer_account_id bigint;
BEGIN
  IF (SELECT auth.uid()) IS NULL
     OR NOT (SELECT private.is_staff())
     OR (
       current_employee IS NULL
       AND NOT (SELECT private.has_role('Quản lý'))
       AND NOT (SELECT private.has_role('Chủ cửa hàng'))
     ) THEN
    RAISE EXCEPTION 'An active staff account is required';
  END IF;
  SELECT *
  INTO order_record
  FROM public."DonHang"
  WHERE "DonHangID" = p_donhangid
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;
  IF p_trangthaimoi=order_record."TrangThai" THEN RETURN; END IF;
  valid_transition := CASE order_record."TrangThai"
    WHEN 'Chờ tiếp nhận' THEN p_trangthaimoi = 'Đã hủy'
    WHEN 'Đã tiếp nhận' THEN p_trangthaimoi IN ('Đang giặt', 'Đã hủy')
    WHEN 'Đang giặt' THEN p_trangthaimoi = 'Hoàn thành giặt'
    WHEN 'Hoàn thành giặt' THEN p_trangthaimoi IN ('Đang giao', 'Đã giao')
    WHEN 'Đang giao' THEN p_trangthaimoi = 'Đã giao'
    ELSE false
  END;
  IF NOT valid_transition THEN
    RAISE EXCEPTION 'Invalid order status transition: % -> %',
      order_record."TrangThai", p_trangthaimoi;
  END IF;
  IF p_trangthaimoi = 'Đã hủy' AND nullif(btrim(p_lydo), '') IS NULL THEN
    RAISE EXCEPTION 'A cancellation reason is required';
  END IF;
  IF p_trangthaimoi='Đã hủy' AND EXISTS (SELECT 1 FROM public."ThanhToan" WHERE "DonHangID"=p_donhangid AND "TrangThai"='Thành công') THEN RAISE EXCEPTION 'Collected payments must be refunded before cancellation'; END IF;
  UPDATE public."DonHang"
  SET "TrangThai" = p_trangthaimoi,
      "NgayCapNhat" = now()
  WHERE "DonHangID" = p_donhangid;
  INSERT INTO public."NhatKyHeThong" (
    "TaiKhoanID", "HanhDong", "BangDuLieu", "BanGhiID",
    "DuLieuCu", "DuLieuMoi", "LyDo", "ThoiGian"
  ) VALUES (
    current_account,
    'Thay đổi trạng thái đơn hàng',
    'DonHang',
    p_donhangid,
    jsonb_build_object('TrangThai', order_record."TrangThai"),
    jsonb_build_object('TrangThai', p_trangthaimoi),
    nullif(left(btrim(p_lydo), 500), ''),
    now()
  );
  customer_account_id := private.account_id_for_customer(order_record."KhachHangID");
  IF customer_account_id IS NOT NULL THEN
    INSERT INTO public."ThongBao" (
      "TaiKhoanID", "TieuDe", "NoiDung", "ThoiGianGui", "DaDoc", "DonHangID", "LoaiThongBao"
    ) VALUES (
      customer_account_id,
      CASE WHEN p_trangthaimoi = 'Đã hủy'
        THEN 'Đơn hàng đã bị hủy'
        ELSE 'Cập nhật trạng thái đơn hàng'
      END,
      'Đơn hàng ' || order_record."MaDonHang" || ' đã chuyển sang trạng thái: ' || p_trangthaimoi || '.',
      now(),
      false,
      p_donhangid,
      CASE WHEN p_trangthaimoi = 'Đã hủy' THEN 'order_cancelled' ELSE 'status_update' END
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.unregister_push_device_token(p_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  account_id bigint;
BEGIN
  IF auth.uid() IS NULL OR p_token IS NULL THEN
    RETURN;
  END IF;

  account_id := private.current_account_id();
  IF account_id IS NOT NULL THEN
    DELETE FROM public.push_device_tokens
    WHERE token = p_token AND "TaiKhoanID" = account_id::integer;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_customer_profile(p_full_name text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := (SELECT private.current_customer_id());
  account_id bigint;
BEGIN
  IF customer_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF nullif(btrim(p_full_name), '') IS NULL THEN
    RAISE EXCEPTION 'Full name is required';
  END IF;

  SELECT "TaiKhoanID"
  INTO account_id
  FROM public."TaiKhoan"
  WHERE "KhachHangID" = customer_id
    AND "UserAuthId" = (SELECT auth.uid())
  LIMIT 1;

  UPDATE public."KhachHang"
  SET "HoTen" = left(btrim(p_full_name), 150),
      "Email" = nullif(left(btrim(p_email), 255), ''),
      "SoDienThoai" = nullif(left(btrim(p_phone), 20), ''),
      "DiaChi" = nullif(left(btrim(p_address), 255), '')
  WHERE "KhachHangID" = customer_id;

  UPDATE public."TaiKhoan"
  SET "Email" = nullif(left(btrim(p_email), 255), ''),
      "SoDienThoai" = nullif(left(btrim(p_phone), 20), '')
  WHERE "TaiKhoanID" = account_id;

  RETURN jsonb_build_object('khachhangid', customer_id, 'taikhoanid', account_id);
END;
$function$
